mapper.select:
SELECT user_id, expire_time
FROM user_member
WHERE user_id = #{userId}

mapper.update:
UPDATE user_member
SET expire_time = #{expireTime}
WHERE user_id = #{userId}

mapper.select:
SELECT user_id, expire_time
FROM user_member
WHERE expire_time >= #{fromTime}
  AND expire_time <= #{toTime}
ORDER BY expire_time ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM user_member
WHERE expire_time >= #{fromTime}
  AND expire_time <= #{toTime}
